function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),3200);}
function persist(immediate=false){state.updatedAt=Date.now();if(state.active){state.active.updatedAt=state.updatedAt;backupActive(state.active,state.customExercises);}const snapshot=structuredClone(state);if(saveTimeout)clearTimeout(saveTimeout);if(immediate){commit(snapshot);return;}saveTimeout=setTimeout(()=>commit(structuredClone(state)),160);}
function commit(snapshot){saveTimeout=null;const write=saveChain.catch(()=>{}).then(()=>storeState(snapshot));saveChain=write.catch(err=>{console.error(err);toast('Problema di salvataggio. Esporta un backup appena possibile.');});return write;}
