function modalView(){if(!modal)return '';let body='';const textInput=(key,label,placeholder='',type='text')=>field(label,modal.fields?.[key]??'','modal-text',{placeholder,type,data:{key}});
if(['new-program','rename-program','new-day','edit-day','add-gym','superset'].includes(modal.type)){
const titles={'new-program':'Crea una scheda','rename-program':'Rinomina scheda','new-day':'Aggiungi un giorno','edit-day':'Modifica giorno','add-gym':'Aggiungi palestra','superset':'Collega una superserie'};
body=`<h2>${titles[modal.type]}</h2><div class="stack mt12">${textInput('name',modal.type==='superset'?'Gruppo superserie (es. A)':modal.type==='add-gym'?'Nome della palestra':modal.type.includes('day')?'Nome del giorno':'Nome del programma',modal.type.includes('day')?'Giorno 1':'La mia scheda')}${modal.type.includes('day')?textInput('focus','Distretti muscolari (facoltativo)','Es. Petto, spalle e tricipiti'):''}${btn('Salva','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='catalog'){
body=`<h2>${modal.mode==='session-replace'||modal.mode==='plan-replace'?'Sostituisci esercizio':'Aggiungi esercizio'}</h2><p class="sub">Scegli dal catalogo oppure crea una variante personalizzata.</p><div class="mt12">${field('Cerca per nome o variante',modal.query||'','catalog-search',{placeholder:'Es. panca Scott, lat machine, squat'})}</div><div class="row mt12 mb12">${btn('Cerca nel catalogo','catalog-list',{kind:!modal.custom?'':'secondary',size:'small'})}${btn('Esercizio personalizzato','catalog-custom',{kind:modal.custom?'':'secondary',size:'small',icon:'plus'})}</div>${modal.custom?`<div class="stack">${textInput('name','Nome esercizio','Scrivi il nome che preferisci')}<div class="field"><label>Distretto muscolare principale</label>${select(muscleOptions(),modal.fields.primary,'modal-primary')}</div><div class="field"><label>Regione anatomica per il Check-up</label>${select(regionOptions(modal.fields.primary),modal.fields.checkupRegion||'','modal-detail')}</div><div class="field"><label>Muscoli secondari (facoltativi)</label><div class="row wrap">${MUSCLES.filter(m=>m[0]!==modal.fields.primary).map(([id,name])=>`<label class="pill" style="cursor:pointer"><input type="checkbox" data-bind="modal-secondary" data-key="${id}" ${(modal.fields.secondary||[]).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}</div></div>${btn('Crea e usa esercizio','create-custom',{full:true,icon:'plus'})}</div>`:
`<div class="search-results" id="catalog-results">${catalogResultHTML()}</div>`}
${modal.mode==='session-replace'?`<div class="mt12"><label class="row small"><input type="checkbox" data-bind="catalog-permanent" ${modal.permanent?'checked':''}/> Salva la sostituzione anche nella scheda permanente</label></div>`:''}`;
}else if(modal.type==='edit-custom'){
body=`<h2>Modifica esercizio personalizzato</h2><div class="stack mt12">${textInput('name','Nome esercizio','Nome personalizzato')}<div class="field"><label>Muscolo principale</label>${select(muscleOptions(),modal.fields.primary,'modal-primary')}</div><div class="field"><label>Regione anatomica per il Check-up</label>${select(regionOptions(modal.fields.primary),modal.fields.checkupRegion||'','modal-detail')}</div><div class="field"><label>Muscoli secondari</label><div class="row wrap">${MUSCLES.filter(m=>m[0]!==modal.fields.primary).map(([id,name])=>`<label class="pill"><input type="checkbox" data-bind="modal-secondary" data-key="${id}" ${(modal.fields.secondary||[]).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}</div></div>${btn('Salva esercizio','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='config'){
const a=modal.temp;body=`<h2>Configura esercizio</h2><p class="sub">${esc($ex(a.exerciseId)?.name||'Esercizio')}</p><div class="stack mt12">${field('Nome visualizzato (facoltativo)',a.label||'','assignment-field',{placeholder:'Es. Scott EZ Palestra 2',data:{key:'label'}})}${field('Numero serie',a.setCount,'assignment-field',{type:'number',min:1,data:{key:'setCount'}})}<div class="stat-grid">${field('Reps minime',a.targetMin,'assignment-field',{type:'number',min:1,data:{key:'targetMin'}})}${field('Reps massime',a.targetMax,'assignment-field',{type:'number',min:1,data:{key:'targetMax'}})}${field('RIR obiettivo',a.targetRir,'assignment-field',{type:'number',min:0,data:{key:'targetRir'}})}${field('Recupero (secondi)',a.restSec,'assignment-field',{type:'number',min:0,data:{key:'restSec'}})}</div><label class="row"><input class="check" type="checkbox" data-bind="assignment-unilateral" ${a.unilateral?'checked':''}/> Esecuzione unilaterale (SX / DX)</label>${field('Gruppo superserie (facoltativo)',a.supersetGroup||'','assignment-field',{placeholder:'Es. A: esercizi con lo stesso gruppo sono collegati',data:{key:'supersetGroup'}})}${btn('Salva configurazione','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='copy-day'){
const gymOpts=state.gyms.filter(g=>g.id!==state.gymId);body=`<h2>Copia esercizi da un'altra palestra</h2><p class="sub">Copierai gli esercizi del giorno selezionato nella palestra ${esc(gymName(state.gymId))}. Gli storici rimarranno separati.</p>${gymOpts.length?`<div class="field mt12"><label>Palestra di origine</label>${select(gymOpts.map(g=>({value:g.id,label:g.name})),modal.fields.source,'modal-source')}</div><div class="inline-alert mt12">Gli eventuali esercizi già configurati per questa palestra saranno sostituiti.</div>${btn('Copia scheda del giorno','modal-save',{full:true,icon:'layers'})}`:'<p class="sub">Aggiungi prima un’altra palestra.</p>'}`;
}else if(modal.type==='session-menu'){
const active=state.active,entry=active?.entries[Math.min(active.focusIndex||0,active.entries.length-1)],rest=active?.restTimer;
body=`<h2>Gestisci allenamento</h2><p class="sub">${esc(active?.dayName||'')} · ${esc(gymName(active?.gymId))}</p>
<div class="menu-section"><div class="row between"><div><strong>Durata della seduta</strong><p class="sub"><span class="live-duration">${formatDuration(sessionSeconds(active))}</span></p></div>${btn(active?.pausedAt?'Riprendi':'Metti in pausa',active?.pausedAt?'resume-session':'pause-session',{kind:'secondary',size:'small',icon:active?.pausedAt?'play':'pause'})}</div></div>
<div class="menu-section"><h3>Timer recupero manuale</h3><p class="sub">Non si avvia quando spunti una serie.</p>${rest&&rest.endsAt>Date.now()?`<div class="rest-running">${ic('clock',20)} <b class="live-rest" data-rest-entry="${esc(rest.entryId)}">${formatDuration((rest.endsAt-Date.now())/1000).slice(3)}</b>${btn('Ferma','stop-rest',{kind:'danger',size:'small'})}</div>`:entry?`<p class="small muted">${esc(entry.name)} · ${entry.restSec} secondi</p>${btn('Avvia recupero','start-rest',{kind:'secondary',full:true,icon:'clock',data:{id:entry.id}})}`:'<p class="sub">Aggiungi prima un esercizio.</p>'}</div>
<div class="menu-section"><h3>Altre azioni</h3>${btn('Ritorna all’allenamento','modal-close',{kind:'secondary',full:true})}${btn('Vai alla Home senza chiudere','go',{kind:'ghost',full:true,data:{to:'home'}})}${btn('Abbandona senza salvare','request-abandon',{kind:'danger',full:true,icon:'trash'})}</div>`;
}else if(modal.type==='abandon'){
body=`<div class="abandon-icon">${ic('trash',28)}</div><h2>Abbandonare l’allenamento?</h2><p class="sub">La seduta avviata per errore verrà eliminata senza comparire nello storico. Serie e note scritte in questa sessione andranno perse.</p><div class="stack mt12">${btn('Continua allenamento','modal-close',{kind:'secondary',full:true})}${btn('Salva come parziale','finish-session',{kind:'ghost',full:true,data:{status:'partial'}})}${btn('Abbandona senza salvare','abandon-session',{kind:'danger',full:true})}</div>`;
}else if(modal.type==='confirm'){
body=`<h2>${esc(modal.title||'Conferma')}</h2><p class="sub mt12">${esc(modal.message||'Confermi questa operazione?')}</p><div class="row mt12">${btn('Conferma','confirm-yes',{kind:'danger',full:true})}${btn('Annulla','modal-close',{kind:'secondary',full:true})}</div>`;
}
return `<div class="overlay" role="presentation" data-action="overlay-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(modal.type)}"><div class="modal-head"><span class="eyebrow">REPz</span>${btn(ic('close',18),'modal-close',{kind:'ghost',size:'small'})}</div>${body}</section></div>`;}
function catalogResultHTML(){if(!modal||modal.type!=='catalog')return '';const exs=matchExercises(exerciseOptions(),modal.query||'');return exs.length?exs.map(e=>`<button class="search-result" data-action="select-exercise" data-id="${e.id}"><b>${esc(e.name)}</b><p class="sub tiny">${esc(muscleName(e.primary))} · ${esc(e.equipment||'Personalizzato')} ${e.custom?'· Personalizzato':''}</p></button>`).join(''):'<div class="empty"><p class="sub">Nessun esercizio corrispondente. Puoi crearlo manualmente.</p></div>';}
function openModal(type,extra={}){modal={type,fields:{},...extra};redraw();setTimeout(()=>{const el=app.querySelector('.modal .input');if(el)el.focus();},70);}
function modalSave(){if(!modal)return;const m=modal,p=$program(),d=$day();if(['new-program','rename-program','new-day','edit-day','add-gym','superset'].includes(m.type)){
const name=(m.fields.name||'').trim();if(!name&&m.type!=='superset'){toast('Inserisci un nome.');return;}if(m.type==='superset'){const e=$entry(m.id);if(e)e.supersetGroup=name;}if(m.type==='new-program'){const v={id:uid('prog'),name,archived:false,days:[],nextDayId:null};state.programs.push(v);state.programId=v.id;selectedDay=null;}
if(m.type==='rename-program'&&p)p.name=name;
if(m.type==='new-day'&&p){const newDay={id:uid('day'),name,focus:(m.fields.focus||'').trim(),byGym:{}};p.days.push(newDay);if(!p.nextDayId)p.nextDayId=newDay.id;selectedDay=newDay.id;}
if(m.type==='edit-day'&&d){d.name=name;d.focus=(m.fields.focus||'').trim();}
if(m.type==='add-gym'){const id=uid('gym');state.gyms.push({id,name});state.gymId=id;}
}else if(m.type==='edit-custom'){
const ex=state.customExercises.find(x=>x.id===m.id);if(!ex)return;const name=(m.fields.name||'').trim();if(!name){toast('Inserisci il nome.');return;}ex.name=name;ex.primary=m.fields.primary;ex.checkupRegion=m.fields.checkupRegion||null;ex.secondary=(m.fields.secondary||[]).filter(x=>x!==ex.primary);
}else if(m.type==='config'){
const a=assignments(d).find(x=>x.id===m.temp.id);if(!a){toast('Esercizio non trovato.');return;}const vals=m.temp;if(num(vals.setCount)<1||num(vals.targetMax)<num(vals.targetMin)){toast('Controlla serie e intervallo ripetizioni.');return;}
Object.assign(a,{setCount:Math.max(1,Math.min(30,Math.floor(num(vals.setCount)))),targetMin:num(vals.targetMin),targetMax:num(vals.targetMax),targetRir:num(vals.targetRir),restSec:num(vals.restSec),unilateral:!!vals.unilateral,supersetGroup:String(vals.supersetGroup||''),label:String(vals.label||'').trim()});
}else if(m.type==='copy-day'){
if(!d||!m.fields.source)return;d.byGym=d.byGym||{};d.byGym[state.gymId]=(d.byGym[m.fields.source]||[]).map(a=>({...structuredClone(a),id:uid('assign')}));
}else return;
if(m.type==='new-program')page='plan-editor';modal=null;persist();redraw({top:m.type==='new-program'});toast('Salvato.');}
function selectedExercise(id){const ex=$ex(id),m=modal;if(!ex||!m)return;const p=$program(),d=$day();if(m.mode==='plan-add'){d.byGym=d.byGym||{};if(!d.byGym[state.gymId])d.byGym[state.gymId]=[];d.byGym[state.gymId].push({id:uid('assign'),exerciseId:ex.id,setCount:3,targetMin:8,targetMax:12,targetRir:2,restSec:state.settings.restDefault,unilateral:false,supersetGroup:'',label:''});}
else if(m.mode==='plan-replace'){const a=assignments(d).find(a=>a.id===m.id);if(a)a.exerciseId=ex.id;}
else if(m.mode==='session-insert'){if(!state.active)return;const newEntry=makeEntry(ex,null,true);const pos=Math.max(0,Math.min(state.active.entries.length,Number(m.index)+1));state.active.entries.splice(pos,0,newEntry);state.active.expandedId=newEntry.id;state.active.focusIndex=pos;}
else if(m.mode==='session-replace'){const e=$entry(m.id);if(!e)return;if(doneSets(e).length&&!confirm('Questo esercizio ha serie già completate. Sostituendolo, i dati delle serie attuali verranno azzerati. Continuare?'))return;const originalId=e.originalId||e.exerciseId,originalName=e.originalName||e.name;const newE=makeEntry(ex,null,e.extra);Object.assign(e,{exerciseId:newE.exerciseId,name:newE.name,originalId,originalName,sets:newE.sets,feedback:'',restSec:newE.restSec,unilateral:newE.unilateral,expanded:true});
if(m.permanent&&e.plannedAssignmentId){const parentProgram=state.programs.find(x=>x.id===state.active.programId);const actualDay=parentProgram?.days.find(x=>x.id===state.active.dayId);const a=assignments(actualDay,state.active.gymId).find(x=>x.id===e.plannedAssignmentId);if(a)a.exerciseId=ex.id;}}
modal=null;persist(true);redraw();toast('Esercizio inserito e collegato allo storico.');}
const downloadFile=(content,name,type)=>{const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);};
function confirmModal(title,message,handler){openModal('confirm',{title,message,handler});}
function handleAction(action,d){const p=$program(),day=$day(),s=state.active;
switch(action){
case 'go':if(d.to==='workout'&&!s){page='workout';redraw({top:true});return;}navigate(d.to);return;
case 'choose-gym':state.gymId=d.id;persist();redraw();return;
case 'open-editor':state.programId=d.id;selectedDay=null;persist();navigate('plan-editor');return;
case 'new-program':openModal('new-program',{fields:{name:''}});return;
case 'archive-program':if(p){p.archived=!p.archived;if(p.archived){const next=state.programs.find(x=>!x.archived&&x.id!==p.id);if(next){state.programId=next.id;selectedDay=null;}}persist();redraw();toast(p.archived?'Scheda archiviata. Puoi ripristinarla quando vuoi.':'Scheda ripristinata.');}return;
case 'rename-program':if(p)openModal('rename-program',{fields:{name:p.name}});return;
case 'new-day':if(p)openModal('new-day',{fields:{name:`Giorno ${p.days.length+1}`,focus:''}});return;
case 'edit-day':if(day)openModal('edit-day',{fields:{name:day.name,focus:day.focus||''}});return;
case 'choose-day':selectedDay=d.id;redraw();return;
case 'delete-program':if(p)confirmModal('Eliminare la scheda?',`La scheda "${p.name}" verrà eliminata, ma lo storico delle sedute rimarrà disponibile.`,()=>{state.programs=state.programs.filter(x=>x.id!==p.id);state.programId=state.programs[0]?.id||null;selectedDay=null;});return;
case 'delete-day':if(day)confirmModal('Eliminare il giorno?',`Il giorno "${day.name}" verrà rimosso dalla scheda. Le vecchie sedute rimarranno nello storico.`,()=>{p.days=p.days.filter(x=>x.id!==day.id);if(p.nextDayId===day.id)p.nextDayId=p.days[0]?.id||null;selectedDay=null;});return;
case 'browse-catalog':openModal('catalog',{mode:d.mode,id:d.id,index:d.index!==undefined?Number(d.index):null,permanent:false,custom:false,query:'',fields:{name:'',primary:'bicipiti',secondary:[]}});return;
case 'catalog-list':modal.custom=false;redraw();return;
case 'catalog-custom':modal.custom=true;modal.fields.name=modal.query||modal.fields.name||'';redraw();return;
case 'create-custom':{const name=modal.fields.name?.trim();if(!name){toast('Scrivi il nome dell’esercizio.');return;}const ex={id:uid('custom'),name,primary:modal.fields.primary||'bicipiti',checkupRegion:modal.fields.checkupRegion||null,secondary:(modal.fields.secondary||[]).filter(x=>x!==modal.fields.primary),equipment:'Personalizzato',aliases:[],custom:true};state.customExercises.push(ex);selectedExercise(ex.id);return;}
case 'select-exercise':selectedExercise(d.id);return;
case 'config-assignment':{const a=assignments(day).find(x=>x.id===d.id);if(a)openModal('config',{temp:structuredClone(a)});return;}
case 'remove-assignment':{const a=assignments(day).find(x=>x.id===d.id);if(!a)return;confirmModal('Rimuovere l’esercizio?',`Verrà tolto dalla scheda. Lo storico di "${$ex(a.exerciseId)?.name||''}" resterà salvato.`,()=>{day.byGym[state.gymId]=assignments(day).filter(x=>x.id!==a.id);});return;}
case 'move-assignment':{const list=assignments(day),i=list.findIndex(x=>x.id===d.id),j=i+Number(d.delta);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];persist();redraw();return;}
case 'copy-day':{const g=state.gyms.find(g=>g.id!==state.gymId);openModal('copy-day',{fields:{source:g?.id||''}});return;}
case 'start-day':beginWorkout(d.id);return;
case 'next-entry':if(s?.entries.length){s.focusIndex=Math.min(s.entries.length-1,(s.focusIndex||0)+1);s.expandedId=s.entries[s.focusIndex].id;persist();redraw({top:true});}return;
case 'prev-entry':if(s?.entries.length){s.focusIndex=Math.max(0,(s.focusIndex||0)-1);s.expandedId=s.entries[s.focusIndex].id;persist();redraw({top:true});}return;
case 'jump-entry':if(s?.entries.length){s.focusIndex=Math.max(0,Math.min(s.entries.length-1,Number(d.index)||0));s.expandedId=s.entries[s.focusIndex].id;persist();redraw({top:true});}return;
case 'session-menu':if(s)openModal('session-menu');return;
case 'request-abandon':if(s)openModal('abandon');return;
case 'abandon-session':abandonWorkout();return;
case 'toggle-entry':{const e=$entry(d.id);if(e){e.expanded=e.expanded===false?true:false;s.expandedId=e.id;persist();redraw();}return;}
case 'toggle-unilateral':{const e=$entry(d.id);if(e){e.unilateral=!e.unilateral;persist();redraw();}return;}
case 'add-set':{const e=$entry(d.id);if(e){e.sets.push(makeSet());persist();redraw();}return;}
case 'remove-set':{const e=$entry(d.id);if(!e||e.sets.length<2)return;if(e.sets.at(-1).done){confirmModal('Rimuovere la serie?', 'La serie finale è completata. Vuoi davvero eliminarla?',()=>e.sets.pop());return;}e.sets.pop();persist();redraw();return;}
case 'remove-entry':{const e=$entry(d.id);if(!e)return;confirmModal('Rimuovere esercizio dalla seduta?',`L'esercizio "${e.name}" verrà rimosso solo dalla seduta attuale.`,()=>{const i=s.entries.findIndex(x=>x.id===e.id);s.entries=s.entries.filter(x=>x.id!==e.id);s.focusIndex=Math.min(Math.max(0,s.focusIndex||0),s.entries.length-1);if(i<(s.focusIndex||0))s.focusIndex=Math.max(0,s.focusIndex-1);});return;}
case 'move-entry':{const i=s.entries.findIndex(e=>e.id===d.id),j=i+Number(d.delta);if(j<0||j>=s.entries.length)return;[s.entries[i],s.entries[j]]=[s.entries[j],s.entries[i]];s.focusIndex=j;persist();redraw();return;}
case 'start-rest':{const e=$entry(d.id);if(!e)return;s.restTimer={entryId:e.id,endsAt:Date.now()+num(e.restSec)*1000};persist(true);redraw();return;}
case 'stop-rest':s.restTimer=null;persist();redraw();return;
case 'pause-session':s.pausedAt=Date.now();persist(true);redraw();return;
case 'resume-session':if(s.pausedAt){s.pausedMs+=Date.now()-s.pausedAt;s.pausedAt=null;persist(true);}redraw();return;
case 'show-finish':navigate('finish');return;
case 'finish-session':modal=null;finishWorkout(d.status);return;
case 'session-detail':historySessionId=d.id;navigate('history');return;
case 'close-history-detail':historySessionId=null;redraw({top:true});return;
case 'select-history-date':historyDate=d.day;redraw();return;
case 'history-month':{const base=historyDate?new Date(historyDate+'T12:00:00'):new Date();const y=base.getFullYear(),m=base.getMonth()+Number(d.delta);historyDate=dateKey(new Date(y,m,1).getTime());redraw();return;}
case 'metric':progressMetric=d.id;redraw();return;
case 'muscle-period':musclePeriod=d.id;redraw();return;
case 'anatomy-side':anatomySide=d.id==='back'?'back':'front';redraw();return;
case 'focus-muscle':muscleFocus=d.id;redraw();setTimeout(()=>document.querySelector('.muscle-info')?.scrollIntoView({behavior:'smooth',block:'center'}),20);return;
case 'set-superset':{const e=$entry(d.id);if(e)openModal('superset',{id:e.id,fields:{name:e.supersetGroup||''}});return;}
case 'edit-custom':{const ex=state.customExercises.find(x=>x.id===d.id);if(ex)openModal('edit-custom',{id:ex.id,fields:{name:ex.name,primary:ex.primary,checkupRegion:ex.checkupRegion||'',secondary:[...ex.secondary]}});return;}
case 'add-gym':openModal('add-gym',{fields:{name:`Palestra ${state.gyms.length+1}`}});return;
case 'modal-save':modalSave();return;
case 'confirm-yes':{const h=modal?.handler;modal=null;if(h)h();persist();redraw();toast('Operazione completata.');return;}
case 'modal-close':modal=null;redraw();return;
case 'overlay-close':modal=null;redraw();return;
case 'share-summary':shareSummary();return;
case 'export-json':{const filename=`REPz_backup_${dateKey(Date.now())}.json`;downloadFile(JSON.stringify({...state,backupCreatedAt:new Date().toISOString()},null,2),filename,'application/json;charset=utf-8');toast('Backup esportato. Conservalo in un posto sicuro.');return;}
case 'export-csv':downloadFile(exportCSV(state),`REPz_storico_${dateKey(Date.now())}.csv`,'text/csv;charset=utf-8');toast('Storico CSV esportato.');return;
}
}
let finishing=false;async function finishWorkout(status){const s=state.active;if(!s||finishing)return;finishing=true;const current=structuredClone(s);const end=Date.now();current.endedAt=end;if(current.pausedAt){current.pausedMs+=end-current.pausedAt;current.pausedAt=null;}current.status=status==='partial'?'partial':'complete';current.restTimer=null;const p=state.programs.find(p=>p.id===current.programId),oldNextDay=p?.nextDayId;if(p&&current.status==='complete'){const idx=p.days.findIndex(d=>d.id===current.dayId);if(idx!==-1&&p.days.length)p.nextDayId=p.days[(idx+1)%p.days.length].id;}state.sessions.push(current);state.active=null;state.updatedAt=Date.now();try{if(saveTimeout)clearTimeout(saveTimeout);await commit(structuredClone(state));backupActive(null);historySessionId=current.id;page='history';redraw({top:true});toast('Allenamento salvato nello storico.');}catch(err){state.sessions.pop();state.active=s;if(p)p.nextDayId=oldNextDay;backupActive(s,state.customExercises);redraw();toast('Salvataggio non riuscito, allenamento recuperato.');}finally{finishing=false;}}

let abandoning=false;
async function abandonWorkout(){if(!state.active||abandoning)return;abandoning=true;const session=state.active;modal=null;state.active=null;state.updatedAt=Date.now();try{if(saveTimeout)clearTimeout(saveTimeout);await commit(structuredClone(state));backupActive(null);page='home';redraw({top:true});toast('Seduta annullata: nessun dato aggiunto allo storico.');}catch(err){state.active=session;backupActive(session,state.customExercises);page='workout';redraw();toast('Impossibile annullare: il salvataggio non è riuscito.');}finally{abandoning=false;}}

async function shareSummary(){const s=state.active;if(!s)return;const m=workoutMetrics(s),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1320;const ctx=canvas.getContext('2d');if(!ctx)return;ctx.fillStyle='#10151C';ctx.fillRect(0,0,1080,1320);ctx.fillStyle='#35D8C5';ctx.fillRect(72,80,14,100);ctx.fillStyle='#F8FAFC';ctx.font='bold 96px Arial';ctx.fillText('REPz',110,166);ctx.fillStyle='#C1CCD9';ctx.font='36px Arial';ctx.fillText(`${s.dayName} · ${gymName(s.gymId)}`,75,242);ctx.fillStyle='#222C38';ctx.fillRect(64,315,950,340);ctx.fillStyle='#35D8C5';ctx.font='bold 30px Arial';ctx.fillText('TONNELLAGGIO TOTALE',102,384);ctx.fillStyle='#FFFFFF';ctx.font='bold 98px Arial';ctx.fillText(`${dval(m.volume)} kg`,100,522);ctx.font='36px Arial';ctx.fillStyle='#FFB36B';ctx.fillText(`${m.sets} serie · ${m.reps} reps · ${formatDuration(sessionSeconds(s))}`,104,609);ctx.fillStyle='#FFFFFF';ctx.font='bold 58px Arial';ctx.fillText('IL MIO ALLENAMENTO',74,767);ctx.font='35px Arial';ctx.fillStyle='#C1CCD9';ctx.fillText(`Record: ${workoutPRs(s).length}`,78,837);ctx.fillText(`Densità: ${dval(m.density)} kg/min`,78,900);ctx.fillText(`Calorie stimate: ${m.kcal?'~'+Math.round(m.kcal)+' kcal':'non disponibili'}`,78,963);ctx.fillStyle='#9AAABB';ctx.font='27px Arial';ctx.fillText('Statistiche personali · Stime indicate come tali',78,1205);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)return;const filename='REPz_riepilogo.png';try{const file=new File([blob],filename,{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:'Riepilogo REPz'});return;}}catch(e){if(e.name==='AbortError')return;}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.download=filename;a.href=url;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Immagine riepilogo creata.');}
function updateInput(el){const type=el.dataset.bind;if(!type)return;const v=el.type==='checkbox'?el.checked:el.value;let rerender=false;switch(type){
case 'modal-text':modal.fields[el.dataset.key]=v;return;
case 'modal-primary':modal.fields.primary=v;modal.fields.checkupRegion='';modal.fields.secondary=(modal.fields.secondary||[]).filter(x=>x!==v);redraw();return;
case 'modal-detail':modal.fields.checkupRegion=v;return;
case 'modal-secondary':modal.fields.secondary=modal.fields.secondary||[];if(v&&!modal.fields.secondary.includes(el.dataset.key))modal.fields.secondary.push(el.dataset.key);if(!v)modal.fields.secondary=modal.fields.secondary.filter(x=>x!==el.dataset.key);return;
case 'modal-source':modal.fields.source=v;return;
case 'modal-config':return;
case 'catalog-permanent':modal.permanent=v;return;
case 'catalog-search':modal.query=v;{const results=document.getElementById('catalog-results');if(results)results.innerHTML=catalogResultHTML();}return;
case 'assignment-field':modal.temp[el.dataset.key]=v;return;
case 'assignment-unilateral':modal.temp.unilateral=v;return;
case 'program-select':state.programId=v;selectedDay=null;rerender=true;break;
case 'gym-name':{const g=state.gyms.find(x=>x.id===el.dataset.id);if(g)g.name=v||'Palestra senza nome';break;}
case 'settings':state.settings[el.dataset.key]=el.type==='number'||el.tagName==='SELECT'?num(v):v;break;
case 'session-rpe':if(state.active)state.active.rpe=v;rerender=true;break;
case 'session-note':if(state.active)state.active.note=v;break;
case 'entry-feedback':{const e=$entry(el.dataset.entry);if(e)e.feedback=v;break;}
case 'entry-rest':{const e=$entry(el.dataset.entry);if(e)e.restSec=num(v);break;}
case 'set-field':{const s=$set(el.dataset.entry,el.dataset.set);if(s){s[el.dataset.key]=v;if(el.dataset.key==='done')rerender=true;}break;}
case 'progress-exercise':progressExercise=v;rerender=true;break;
case 'progress-gym':progressGym=v;rerender=true;break;
case 'progress-period':progressPeriod=v;rerender=true;break;
case 'muscle-gym':muscleGym=v;rerender=true;break;
default:return;
}
persist();if(rerender)redraw();}
app.addEventListener('keydown',event=>{const muscle=event.target.closest('[data-muscle]');if(muscle&&(event.key==='Enter'||event.key===' ')){event.preventDefault();handleAction('focus-muscle',{id:muscle.dataset.muscle});}});
app.addEventListener('click',event=>{const muscle=event.target.closest('[data-muscle]');if(muscle){handleAction('focus-muscle',{id:muscle.dataset.muscle});return;}const el=event.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='overlay-close'&&event.target!==el)return;event.preventDefault();handleAction(el.dataset.action,el.dataset);});
app.addEventListener('touchstart',event=>{const area=event.target.closest('[data-swipe-area]');if(!area||event.target.closest('input,textarea,select,button,a,label'))return;const t=event.changedTouches[0];workoutSwipeStart={x:t.clientX,y:t.clientY};},{passive:true});
app.addEventListener('touchend',event=>{if(!workoutSwipeStart||page!=='workout'||!state.active)return;const t=event.changedTouches[0],dx=t.clientX-workoutSwipeStart.x,dy=t.clientY-workoutSwipeStart.y;workoutSwipeStart=null;if(Math.abs(dx)<62||Math.abs(dx)<Math.abs(dy)*1.25)return;handleAction(dx<0?'next-entry':'prev-entry',{});},{passive:true});
app.addEventListener('input',event=>{if(event.target.matches('[data-bind]')&&event.target.type!=='checkbox'&&event.target.tagName!=='SELECT')updateInput(event.target);});
app.addEventListener('change',event=>{if(event.target.matches('[data-bind]')&&(event.target.type==='checkbox'||event.target.tagName==='SELECT'))updateInput(event.target);});
app.addEventListener('change',async event=>{if(event.target.id!=='file-import')return;const file=event.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.schema!==1||!Array.isArray(raw.programs)||!Array.isArray(raw.sessions))throw new Error('Formato di backup non valido');if(!confirm('Importando questo backup SOSTITUIRAI tutti i dati attualmente salvati sul dispositivo. Continuare?'))return;state=normalizeLoaded(raw);if(!state.gyms.some(g=>g.id===state.gymId))state.gymId=state.gyms[0].id;backupActive(state.active,state.customExercises);persist(true);historySessionId=null;selectedDay=null;muscleFocus=null;progressExercise=null;page=state.active?'workout':'home';redraw({top:true});toast('Backup importato correttamente.');}catch(err){toast('Impossibile importare il backup: '+err.message);}});
let lastScrollSave=0;window.addEventListener('scroll',()=>{if(!state.active||page!=='workout')return;state.active.scrollY=window.scrollY;const now=Date.now();if(now-lastScrollSave>450){lastScrollSave=now;persist();}},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state.active){backupActive(state.active,state.customExercises);if(saveTimeout){clearTimeout(saveTimeout);commit(structuredClone(state));}}});
window.addEventListener('pagehide',()=>{if(state.active)backupActive(state.active,state.customExercises);if(saveTimeout){clearTimeout(saveTimeout);commit(structuredClone(state));}});
setInterval(()=>{if(!state.active)return;for(const el of document.querySelectorAll('.live-duration'))el.textContent=formatDuration(sessionSeconds(state.active));const t=state.active.restTimer;if(t){const diff=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));for(const el of document.querySelectorAll('.live-rest')){if(el.dataset.restEntry===t.entryId)el.textContent=formatDuration(diff).slice(3);}if(diff===0){state.active.restTimer=null;persist();if(page==='workout'){redraw();toast('Recupero terminato.');}}}},1000);
async function init(){try{const saved=await loadState();state=normalizeLoaded(saved);}catch(err){console.error(err);state=initialState();toast('Archivio locale non disponibile: controlla le impostazioni di Safari.');}
const recovery=readActiveBackup();if(recovery?.active&&!state.sessions.some(s=>s.id===recovery.active.id)&&(!state.active||recovery.updatedAt>=state.active.updatedAt)){state.active=recovery.active;for(const ex of recovery.customExercises||[]){if(!state.customExercises.some(c=>c.id===ex.id))state.customExercises.push(ex);}persist(true);}if(!state.gyms.some(g=>g.id===state.gymId))state.gymId=state.gyms[0]?.id||'g1';if(state.programId&&!state.programs.some(p=>p.id===state.programId))state.programId=state.programs[0]?.id||null;page=state.active?'workout':'home';redraw({top:true});if(state.active&&state.active.scrollY>0)setTimeout(()=>window.scrollTo(0,state.active.scrollY),150);
if('serviceWorker'in navigator&&location.protocol.startsWith('http')){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache',err));}}
init();

export const __testing={getState:()=>state,getPage:()=>page,getModal:()=>modal,action:handleAction,input:updateInput,render:layout,checkupStats,beginWorkout,previousExecution:(exerciseId,gymId)=>previousExecution(state,exerciseId,gymId),reset:()=>{state=initialState();page='home';selectedDay=null;historySessionId=null;modal=null;}};
